"use client";
import"../../styles/HeroSection.css";

import { useEffect, useState } from "react";

const slides = [
  { label: "Cloud Control", control: "Cloud", title: "Infrastructure control for distributed operations.", description: "Platform services that coordinate resources, identities, policies, and automation across connected environments.", image: "https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1800&q=85", meta: "01 / Cloud orchestration", action: "Explore platform" },
  { label: "Compute & HPC", control: "Compute", title: "Compute systems for demanding workloads.", description: "High-performance environments for scientific workloads, AI training, and enterprise services that need predictable execution.", image: "https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1800&q=85", meta: "02 / Compute & HPC", action: "Explore platform" },
  { label: "Network & Edge", control: "Network", title: "Networks built for operational confidence.", description: "Secure connectivity, routing, and distributed coordination for systems where availability is a permanent requirement.", image: "https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1800&q=85", meta: "03 / Network & edge", action: "Explore platform" },
  { label: "Data & Storage", control: "Data", title: "Data services built for durable access.", description: "Governed storage, databases, and high-performance data flows that preserve availability and control across workloads.", image: "https://images.unsplash.com/photo-1518432031352-d6fc5c10da5a?auto=format&fit=crop&w=1800&q=85", meta: "04 / Data & storage", action: "Explore platform" },
  { label: "Secure Operations", control: "Operations", title: "Security and operations that keep platforms accountable.", description: "Developer delivery, analytics, monitoring, identity, and policy capabilities for measurable, dependable infrastructure.", image: "https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=1800&q=85", meta: "05 / Secure operations", action: "Explore platform" },
];

export default function HeroSection() {
  const [activeSlide, setActiveSlide] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const slide = slides[activeSlide];

  useEffect(() => {
    if (isPaused) return;
    const interval = window.setInterval(() => setActiveSlide((current) => (current + 1) % slides.length), 7000);
    return () => window.clearInterval(interval);
  }, [isPaused]);

  return <section className="hero hero-slider quantum-hero" id="top" aria-roledescription="carousel" aria-label="AtonixCorp infrastructure capabilities" onMouseEnter={() => setIsPaused(true)} onMouseLeave={() => setIsPaused(false)}>
    <div className="hero-slider-image" style={{ backgroundImage: `url(${slide.image})` }} />
    <div className="hero-slider-overlay" />
    <div className="hero-slider-content">
      <p className="hero-slider-label">{slide.label}</p>
      <p className="hero-slider-count">{String(activeSlide + 1).padStart(2, "0")} <span>/ 05</span></p>
      <h1>{slide.title}</h1>
      <p className="hero-slider-description">{slide.description}</p>
      <a className="hero-slider-action" href="#divisions">{slide.action} <span aria-hidden="true">→</span></a>
    </div>
    <div className="hero-slider-footer">
      <p>{slide.meta}</p>
      <div className="hero-slider-controls" aria-label="Select infrastructure capability">
        {slides.map((item, index) => <button key={item.label} type="button" onClick={() => { setActiveSlide(index); setIsPaused(true); }} className={index === activeSlide ? "active" : ""} aria-label={`Show ${item.label}`} aria-current={index === activeSlide ? "true" : undefined}><span>{String(index + 1).padStart(2, "0")}</span>{item.control}</button>)}
      </div>
    </div>
  </section>;
}
